insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values ((select current_version_id from assessments where slug = 'decision-making-under-pressure'), 'Quick Reflection', 'Problems with a fast, appealing, wrong answer and a correct one that takes a moment longer to reach.', 'Answer as quickly as you can — but don''t let that stop you from checking your first instinct.', NULL, false, 0.67, 1);
insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values ((select current_version_id from assessments where slug = 'decision-making-under-pressure'), 'Scenario Judgment', 'Realistic snap decisions made with incomplete information.', 'Choose the best immediate action given only what''s stated.', NULL, false, 0.33, 2);
